INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(5100, 0, 51, 0, 0, 0, 'Searing Gorge', 'The Searing Gorge was born in fire. During the War of the Three Hammers, Sorcerer-Thane Thaurissan of the Dark Iron clan called upon powers sleeping beneath the world and summoned Ragnaros the Firelord. Blackrock Mountain erupted, the Dark Iron capital was thrown down in ruin and the land around it was scorched black, leaving the Burning Steppes to the south and this ravaged valley to the north. Today the gorge is a place of ash, lava and ruthless industry. From Shadowforge City beneath the mountain the Dark Iron dwarves came looking for ore, dug the vast excavation called the Cauldron and filled it with slaves, golems and taskmasters. Fire elementals and lava spiders roam its slopes, and the Twilight''s Hammer keeps a camp in the northwestern hills. Watching all of it from the cliffs of Thorium Point are the Thorium Brotherhood, Dark Iron smiths who broke with their own kin. To the northeast, the locked gates of Stonewrought Pass shut the gorge away from Loch Modan.', 'warcraft.wiki.gg/wiki/Searing_Gorge (history: Thaurissan, Ragnaros, eruption, Cauldron, Thorium Brotherhood left the Dark Iron clan, Stonewrought Pass locked pre-Cataclysm); npc_text 1834-1838 (Pebblebitty: gate locked, beasts of the gorge); quest 3452 description (Twilight''s Hammer encampment in the northwest mountains); DB spawns by subzone (zone_areas.py)'),
(5101, 1, 51, 1, 0, 0, 'Thorium Point', 'Thorium Point clings to the cliffs in the north of the gorge, a guarded outpost looking straight down into the Cauldron. It is the stronghold of the Thorium Brotherhood, Dark Iron smiths who left their clan and now keep a close eye on everything their former kin do below. Brotherhood lookouts stand watch over the camp, and a wanted board posts bounties against the Dark Iron crews and the thieves who rob the camp. Gryphon and wind rider handlers both keep their mounts here, for the Brotherhood welcomes Alliance and Horde alike, and travelers of either banner come to trade with the master craftsmen of the Point.', 'warcraft.wiki.gg/wiki/Thorium_Point (overlooks the Cauldron, Thorium Brotherhood base); warcraft.wiki.gg/wiki/Searing_Gorge (Brotherhood watches the Dark Irons closely); gameobject 179827 Wanted/Missing/Lost & Found; quests 7701, 7728, 7729; DB spawns in area 1446: Thorium Brotherhood Lookouts 14622, Lanie Reed 2941, Grisha 3305; npc_text 7121 (Burninate sends agents on to Lokhtos Darkbargainer); warcraft.wiki.gg/wiki/Thorium_Brotherhood (skilled craftsmen, base on cliffs over the Cauldron in the far north)'),
(5102, 1, 51, 2, 0, 0, 'The Cauldron', 'At the heart of the gorge lies the Cauldron, an enormous pit the Dark Iron dwarves carved out of the blackened valley floor in their hunger for ore. Scaffolds and cart lines cling to its walls, and heavy war golems lumber along its ramps. Slave workers toil without rest under the whips of Dark Iron slavers and taskmasters, so broken by the labor and the heat that they turn on anyone who interferes, would-be rescuers included. Four sentry towers guard the rim, and fire and magma elementals drift through the crevices below. Even here there is trade: the cutthroat dealers of the Undermarket have set up shop in the Cauldron under the protection of their Dark Iron partners.', 'warcraft.wiki.gg/wiki/The_Cauldron (excavation, Slave Workers driven mad, attack liberators, elementals); warcraft.wiki.gg/wiki/Searing_Gorge (mining, enslaved captives); quest 3463 description (four sentry towers); quest 3385 description (Undermarket base in the Cauldron, ties with the Dark Irons); DB spawns in area 246: Slave Worker, Dark Iron Slaver, Taskmaster, Steamsmith, Heavy War Golem, Scaffold Cars, Magma and Blazing Elementals'),
(5103, 1, 51, 3, 0, 0, 'The Slag Pit', 'The Slag Pit is the mine beneath the Cauldron, a maze of hot tunnels rich in ore. Its Dark Iron crew answers to Overseer Maltorius, once of the Thorium Brotherhood, and sleeps in quarters deep inside. Pools of lava in the lower tunnels are home to ravenous incendosaurs. In one hidden chamber stands the altar of Suntara, where enslaved archaeologists labor without rest around a silent, hulking form called Obsidion. The Dark Irons guard the pit fiercely against anyone who would meddle with their work.', 'warcraft.wiki.gg/wiki/Slag_Pit (underground mine in the Cauldron, hostile Dark Irons, incendosaurs); quests 7701, 7702, 7722, 7727 (Maltorius, sleeping quarters, lava pools); quest 3368 description (excavation team taken to the Cauldron, working on Obsidion); quest 3372 description, gameobject 148498 Altar of Suntara; DB spawns: Incendosaur 9318, Enslaved Archaeologist 8402, Overseer Maltorius 14621, Obsidion 8400; DB spawns: Obsidion 8400 and Enslaved Archaeologists 8402 around the Altar of Suntara 148498 (-6478,-1243)'),
(5104, 1, 51, 4, 0, 0, 'Firewatch Ridge', 'The mountains of the northwestern gorge belong to the Twilight''s Hammer. Their encampment on Firewatch Ridge is held by fire guards, geomancers and dark shamans, while idolaters carry the cult''s relics and symbols of Ragnaros, and Highlord Mastrogonde walks among them. The cult keeps a grim warning on the ridge: a cage holding the spirit of a night elf who once served it, put to death as a blasphemer when he turned back to Elune. Greater lava spiders hunt the slopes around the camp, and lava crabs and fire beetles crawl among the rocks.', 'quest 3452 description (Twilight''s Hammer encampment in the northwest mountains, symbols of Ragnaros); quest 3372 description (Twilight''s Hammer guard a relic in the northwest hills); quest 11952 description (Firewatch Ridge bastion of Twilight activity, ice stones, Tidehunter); npc_text 1922 (Zamael caged as a warning); DB spawns in area 1442: Twilight Fire Guard, Geomancer, Dark Shaman, Idolater, Highlord Mastrogonde, Greater Lava Spider; DB spawns in area 1442: Lava Crab, Fire Beetle; warcraft.wiki.gg/wiki/Firewatch_Ridge (checked; Dark Iron description not used)'),
(5105, 1, 51, 5, 0, 0, 'Grimesilt Dig Site', 'The Grimesilt Dig Site was once worked by the dwarves of Ironforge, but the Dark Iron dwarves have since taken it, and their geologists now work the ground under the watch of watchmen and tempered war golems. Of the last Ironforge excavation to dig here, only its leader, Dorius Stonetender, remains, stretched out on the ground among the diggings, and of his team there is no sign. Another dwarf''s luck is merely embarrassing. When a crew member named Locheed hid from the geologists in an outhouse, they simply locked the door behind him and kept the key, and from inside he still begs passersby for help, and for some silk cloth.', 'warcraft.wiki.gg/wiki/Grimesilt_Dig_Site (Ironforge dig site taken by Dark Irons, Dorius, Locheed); creature_text 8421 group 2 (Suntara stones found at the Grimesilt Digsite); quest 3368 description; quests 4449 and 4451 (descriptions and reward texts); DB spawns in area 247: Dark Iron Geologist, Watchman, Tempered War Golem, Wooden Outhouse 173265, Dorius 8284'),
(5106, 1, 51, 6, 0, 0, 'Dustfire Valley', 'Dustfire Valley is a windswept cut through the northeastern gorge, running north toward Stonewrought Pass and the road to Loch Modan beyond. The Dark Irons hold it as they hold most of the gorge: their geologists search the valley for ore, guarded by tempered war golems, while glassweb spiders spin among the rocks. With the gates of the pass kept locked, the valley leads nowhere for most travelers.', 'warcraft.wiki.gg/wiki/Dustfire_Valley (windswept, runs north to Stonewrought Pass, gates locked pre-Shattering); warcraft.wiki.gg/wiki/Stonewrought_Pass (pass at the northern end of Dustfire Valley); DB spawns in area 1959: Dark Iron Geologist, Tempered War Golem, Glassweb Spider, Door 150137'),
(5107, 1, 51, 7, 0, 0, 'Stonewrought Pass', 'Stonewrought Pass is a dwarven tunnel joining the Searing Gorge to Loch Modan, the work of Franclorn Forgewright, the architect whose stonewrought method of building also raised the great dam of Loch Modan. For years both ends have been sealed with locked gates. On the Loch Modan side a mountaineer keeps the key and turns nearly every traveler away, so most who reach the gorge come by the long road through the Badlands or down from Blackrock Mountain instead.', 'warcraft.wiki.gg/wiki/Stonewrought_Pass (tunnel to Loch Modan, locked gates, Pebblebitty, designed by Franclorn Forgewright); quest 3801 description (Franclorn responsible for the stonewrought method); npc_text 1833-1838 (Pebblebitty); quests 3181, 3182, 3201; warcraft.wiki.gg/wiki/Searing_Gorge (pass locked for years; gorge reached through Blackrock Spire or the Badlands trail)'),
(5108, 1, 51, 8, 0, 0, 'Tanner Camp', 'In the southeast of the gorge stands Tanner Camp, the lonely tent of Sarah Tanner, a master of elemental leatherworking who teaches the craft to those willing to open their minds to the greater powers of substance. Her choice of home is a dangerous one: glassweb spiders hunt the surrounding rocks, the great spider Rekk''tilac roams nearby, and a long passage behind her tent leads toward the lair of Margol the Rager.', 'warcraft.wiki.gg/wiki/Tanner_Camp (Sarah Tanner, passage behind her tent to Margol); quest 5144 description (Elemental Leatherworking); DB spawns in area 1958: Sarah Tanner 7868, Glassweb Spider, Rekk''tilac 8277'),
(5109, 1, 51, 9, 0, 0, 'The Sea of Cinders', 'South of the Cauldron the gorge opens into the Sea of Cinders, a broad flat waste scorched by fire and scoured by hot wind. Ash and embers still rise from the smoldering ground and hang in the air, and little lives here that is not made of flame or used to it: searing lava spiders, magma elementals and fire beetles. Dark Iron lookouts keep watch over the plain, which stretches to the foot of Blackrock Mountain.', 'warcraft.wiki.gg/wiki/Sea_of_Cinders (flat southern area north of Blackrock Mountain, ash and embers, uninhabitable); DB spawns in area 1444: Searing Lava Spider, Magma Elemental, Fire Beetle, Dark Iron Lookout'),
(5110, 1, 51, 10, 0, 0, 'Blackchar Cave', 'In the southwestern corner of the gorge, close under Blackrock Mountain, lies Blackchar Cave, a mysterious cavern that has been sealed shut. What lies within is unknown. The ground before it is anything but quiet: Anvilrage guards from the Dark Iron city patrol nearby, lava spiders and fire beetles creep among the rocks, and the fire lord Overmaster Pyron burns at the approach to the Blackrock quarry.', 'warcraft.wiki.gg/wiki/Blackchar_Cave (sealed, mysterious, southwestern gorge near Blackrock Mountain, face shape on the map); DB spawns in area 1957: Anvilrage Taskmaster 24818, Anvilrage Enforcer 24819, Overmaster Pyron 9026; quest 4262 description (Pyron guards the entrance at the Blackrock Quarry); mod-individual-progression data/sql/world/base/zone_searing_gorge.sql (replaces Anvilrage Taskmaster 24818 and Enforcer 24819, added in 2.3, with the original Anvilrage Overseer 8889 and Warden 8890)'),
(5111, 1, 51, 11, 0, 0, 'Blackrock Mountain', 'The southwestern road of the gorge climbs to Blackrock Mountain, the volcano that stands between the Searing Gorge and the Burning Steppes, with the Dark Iron dwarves in its depths and the orcs of the Blackrock clan in the Spire above. On the gorge side its lower slopes are worked as a quarry, where slaves cut stone under the eyes of Anvilrage guards. A hulking foe known as the Behemoth roams the approach to the mountain.', 'warcraft.wiki.gg/wiki/Searing_Gorge (Blackrock Mountain eruption, Shadowforge City); npc_text 2316-2317 (Franclorn: Thaurissan under Ragnaros built Blackrock Spire); DB spawns in area 1445: Quarry Slave 8917, Anvilrage Taskmaster 24818, Anvilrage Enforcer 24819; The Behemoth 8924 nearby; mod-individual-progression zone_searing_gorge.sql (Anvilrage Taskmaster 24818 and Enforcer 24819 replaced by Overseer 8889 and Warden 8890); burning_steppes.json 4600 and 4610, creature_text 8421 group 3 (Blackrock orcs of Blackrock Spire)'),
(5112, 2, 51, 1, 0, 0, 'Kalaran Windblade', 'Kalaran Windblade keeps a lonely camp on the slopes between Thorium Point and the Cauldron, with no company but his lumbering squire, Maltrake, who says he lives only to serve his master. Kalaran tells of a father slain by the filth of the Cauldron and of Stormwind magistrates who would not even admit this corner of the world exists, and he swears that riches beyond imagining await anyone who helps him take his revenge. When he works his craft he chants in a tongue no one recognizes, and the effort drops him to one knee.', 'npc_text 1953-1955 (Kalaran''s tale); creature_text 8479 (chants in an unknown tongue, falls to one knee exhausted); npc_text 2279 (Maltrake: I live only to serve the master); warcraft.wiki.gg/wiki/Kalaran_Windblade'),
(5113, 2, 51, 2, 0, 0, 'Overseer Oilfist', 'Overseer Oilfist leads the Thorium Brotherhood from Thorium Point. Under his hand the Brotherhood smiths and trades in the shadow of the Dark Iron works below, a company of dwarves who chose to leave the protection and comfort of the Depths to explore the world, or to exploit it, as one of them lets slip. His people are an odd lot, from a blind and tipsy lookout captain to an enforcer laid low by swollen fingers. Oilfist himself does not forgive desertion. When Maltorius left the Brotherhood to command the Dark Iron crew of the Slag Pit, it was by Oilfist''s own order that a bounty was posted for the traitor''s head.', 'warcraft.wiki.gg/wiki/Thorium_Brotherhood (Oilfist leads the Brotherhood); quest 7701 description (by order of Overseer Oilfist); npc_text 7095 (Evonice: left the protection and comfort of the Depths to exploit, er, explore the world); npc_text 7094 (Lolo blind and drunk), 7117 and quest 7723 (Hansel''s fat fingers)'),
(5114, 2, 51, 3, 0, 0, 'Master Smith Burninate', 'Master Smith Burninate is the forge master of Thorium Point, a gruff dwarf who sells a little food and drink on the side. His great worry is fiery flux, the Brotherhood''s prized smithing reagent. When Maltorius deserted, he took the secret recipe with him, something more valuable than a pristine arcane crystal, and Burninate would bet anything it paid for the traitor''s new promotion among the Dark Irons. He wants the plans back, and is sure they lie somewhere near Maltorius, deep inside the Slag Pit.', 'npc_text 7115, 7121 (Burninate gossip); quest 7722 description and reward text; quests 7736, 8241, 8242 completion texts (dwindling fiery flux supply)'),
(5115, 2, 51, 4, 0, 0, 'Lookout Captain Lolo Longstriker', 'The captain of the Thorium Point lookouts is, by his own cheerful admission, as blind as a bat and seldom sober. Lolo Longstriker insists that drink keeps his remaining senses sharp, since everyone knows a dwarf who loses one sense gains in the others, and claims his sense for drink has never been better. It is he who pays the bounty on Overseer Maltorius, posted by Oilfist''s order, though those who come to collect may find him too busy hiccuping to notice them.', 'npc_text 7094 (Lolo gossip); quest 7701 description (see Lolo for the reward) and completion text (can''t ya shee I''m bushy, hic); quest 7701 reward text'),
(5116, 2, 51, 5, 0, 0, 'Hansel Heavyhands', 'Hansel Heavyhands is the Brotherhood''s enforcer, the dwarf they call in when Lolo would rather not spill his ale. He would gladly deal out the pain himself, he says, were it not for his swollen fingers, his bunions and a cold he blames on the frigid climate of the Searing Gorge. Instead he hands the work to others: smashing the heavy war golems around the Cauldron, culling the greater lava spiders, and clearing the incendosaurs from the lava pools of the Slag Pit so the Brotherhood can explore below.', 'npc_text 7117 (Hansel gossip); quests 7723, 7724, 7727 (descriptions and reward texts)'),
(5117, 2, 51, 6, 0, 0, 'Overseer Maltorius', 'Maltorius was once an agent of the Thorium Brotherhood. He went over to the Dark Irons and was rewarded with command of the Slag Pit crew in the Cauldron, a promotion the Brotherhood suspects he bought with their secret recipe for fiery flux. He now rules the mine from deep within its tunnels. At Thorium Point his name is spoken with contempt, and a bounty on his head hangs on the camp''s wanted board.', 'quest 7701 description (rogue Thorium Brotherhood agent, newly hired commander of the Slag Pit crew); quest 7722 description (left the clan with the fiery flux recipe); DB spawn: Overseer Maltorius 14621 in the Slag Pit'),
(5118, 2, 51, 7, 1, 0, 'Dorius Stonetender', 'Dorius Stonetender, brother of Curator Thorius of the Hall of Explorers, led an Ironforge excavation at the Grimesilt Dig Site. Now he lies sprawled among the diggings, groaning that he is bleeding inside and must get back to Ironforge. He makes a trying companion on the road, forever stopping to catch his breath and swearing he must quit smoking, yet quick with his fists when the Dark Irons close in. His one worry, he says, is his team: if anything ever happened to him, they would be stuck in the Cauldron''s mine forever.', 'quest 3367 description (badly injured, bleeding internally, must get back to Ironforge); creature_text 8284 groups 0-4, 8, 9 (escort lines: the Cauldron, the team stuck in the mine, quit smoking, fists); quest 3368 description (letter to his brother); quests 3566 (description and reward text); creature_text 8421 (Lathoric''s confession); smart_scripts 8284, 8417, 8391; warcraft.wiki.gg/wiki/Lathoric_the_Black (Lathoric is Dorius, brother of Thorius)'),
(5119, 2, 51, 8, 0, 0, 'Zamael Lunthistle', 'In a cage on Firewatch Ridge lingers the spirit of Zamael Lunthistle. As a young night elf in Darkshore he fell in with the Twilight''s Hammer and abandoned his faith in Elune, until a vision from the goddess woke him. In repentance he began a prayer etched on a tablet of pure gold, but the cult found it, branded him a blasphemer and put him to death. Bound to the world and caged as a warning to traitors, he asks only that his unfinished prayer be carried to the Temple of the Moon.', 'npc_text 1920-1922 (Zamael''s tale); quests 3377, 3378 (descriptions and reward texts)'),
(5120, 2, 51, 9, 0, 0, 'Margol the Rager', 'Margol the Rager is a monstrous beast that haunts the southeasternmost corner of the gorge, at the end of a long passage behind Sarah Tanner''s camp. Mountaineer Pebblebitty, keeper of the gate at Stonewrought Pass, has faced her and calls her a lady almost as tough as herself, and she names Margol as the test for anyone who wants a key to the pass. Lodged in the beast''s gigantic horn, among its scratches and cracks, is the proof of that old meeting: the broken head of an axe etched with Pebblebitty''s name.', 'quest 3181 description (scratches and cracks, axe head of Mountaineer Pebblebitty lodged in the horn); npc_text 1838 (southeasternmost corner, a lady almost as tough as me, proof of heroics for a key); warcraft.wiki.gg/wiki/Tanner_Camp (passage behind her tent to Margol); quest 3182 reward text, quest 3201 description'),
(5121, 2, 51, 10, 0, 0, 'Overmaster Pyron', 'Overmaster Pyron is a lord of fire who guards the quarry at the foot of Blackrock Mountain, a foul spirit the Dark Iron dwarves summoned into the world. The mages Jalinda Sprig sent from Morgan''s Vigil came back burned or worse, and the elders heeded by Thunderheart of Kargath felt his presence as a disturbance among the elements, a disharmony of flame that threatens the land with endless drought. Both want him ended: the elders to heal the disharmony, Jalinda so that her expedition can make its way into Blackrock Depths.', 'quest 3906 description (Dark Irons summoned a foul spirit, eternal drought, lord of fire at the quarry); quest 4262 description (mages came back crispy or worse; expedition crew to get into Blackrock Depths; Pyron guards the entrance at the Blackrock Quarry); creature_text 9026; quests 3907, 4263'),
(5122, 3, 51, 1, 0, 0, 'Divine Retribution', 'Kalaran Windblade asks for help avenging his father, slain by the filth of the Cauldron, since the magistrates of Stormwind will do nothing. His plan is bold: set the four sentry towers ablaze and blind the Dark Iron defenses before an offensive. For that he needs a torch of flawless flame, made from the hearts of fire elementals and golem oil, a shaft reforged from the thorium daggers of Cauldron taskmasters and slavers, and a casing drawn from a Twilight''s Hammer symbol of Ragnaros. Once the torch is made, his squire Maltrake will explain how it is to be used.', 'npc_text 1954 (father slain, Stormwind magistrate); quests 3441, 3442, 3443, 3452, 3462 descriptions; quest 3463 reward text; creature_text 8480, 8509 (the reveal); gameobject 149502 Hoard of the Black Dragonflight; quest 4022 (molt shown to Cyrus Therepentous, Burning Steppes); smart_scripts 8509, 8479'),
(5123, 3, 51, 2, 1, 0, 'The Suntara Stones', 'At the Grimesilt Dig Site lies Dorius Stonetender, leader of an Ironforge excavation, groaning that he is badly hurt, bleeding inside, and must get back to Ironforge. Help him up and he sets off for the gate at Stonewrought Pass, though he must stop again and again to catch his breath. On the way he points out the Cauldron and begs that it be remembered: if anything ever happened to him, he says, his team would be stuck in that mine forever. The Dark Irons do not mean to let him go easily.', 'quests 3367, 3368, 3371, 3372, 3566 (descriptions and reward texts); creature_text 8284, 8391, 8421; smart_scripts 8284, 8417, 8391; warcraft.wiki.gg/wiki/Lathoric_the_Black'),
(5124, 3, 51, 3, 1, 0, 'The Key to the Gorge', 'Mountaineer Pebblebitty will not open the gate at Stonewrought Pass. The gorge is full of beasts that have killed good dwarves, she says, and if she lets one traveler in she will have to let in everyone. Pressed, she admits there is a back road the orcs paved through the Badlands near Kargath, and offers a key to anyone who returns with proof of heroics, pointing to Margol the Rager in the far southeast of the gorge. Margol''s gigantic horn once carried Pebblebitty''s own broken axe head, but it shatters into a million pieces when pulled free.', 'npc_text 1833-1839 (Pebblebitty); quests 3181, 3182, 3201 (descriptions and reward texts)'),
(5125, 3, 51, 4, 0, 0, 'The Brotherhood and the Slag Pit', 'The Thorium Brotherhood has a quarrel with the Slag Pit, and it is personal. Overseer Maltorius, one of their own, deserted to take command of the Dark Iron crew there, and the Brotherhood believes he paid for the post with their recipe for fiery flux. Thorium Point answers with every weapon it has. Master Smith Burninate wants the stolen plans back, the wanted board offers a bounty on Maltorius''s head, and Taskmaster Scrange pays to cull the Dark Iron taskmasters and slavers and to recover a spyglass and smithing tuyere stolen from the camp. Evonice Sootsmoker has a subtler idea: steal the crew''s pillows, for a Dark Iron cannot sleep without one. Hansel Heavyhands wants golems, lava spiders and incendosaurs cleared so Brotherhood teams can explore the pit.', 'quests 7701, 7702, 7722, 7723, 7724, 7727, 7728, 7729 (descriptions and reward texts); quests 7736, 8241, 8242'),
(5126, 3, 51, 5, 0, 0, 'The Undermarket', 'Nilith Lokrav is a tailor who prizes the shadow silk spun by the spiders of the gorge, a cloth highly sought after by the artisans of her trade. She works in the south of the gorge with Raze, the hulking guardian who smashes on command. Lately a band of shadowsilk poachers has encroached on these lands, slaying spiders by the score without a thought for the future, and Nilith wants them found and ended, beginning in the north. Raze is eager to help: use the staff of command near a poacher, and he will make them rue the day they came to poach here.', 'quests 3379, 3385, 3402 (descriptions and reward texts); creature_text 8439, 8441 (Raze and the staff); DB spawns: Nilith Lokrav 8439 and Raze 8441 in the south of the gorge, Kovic 8444 and Clunk 8447 in area 246');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(5103, 1, 0, 255, 'The captives are the excavation team of Dorius Stonetender, taken from the Grimesilt Dig Site. The power of the Suntara stones has bent their minds to the building of Obsidion, and it drives them on even after their bodies give out. One of them, dying, gasps that the altar of Suntara is the key to their release.', 'quest 3368 description (team enslaved by the stones, taken to the Cauldron, working on Obsidion); quest 3372 description (even after their bodies give out the power of the Suntara forces them; the altar is the key), offered on the turn-in of 3371 by the Dying Archaeologist 8417 in the Slag Pit'),
(5105, 1, 0, 255, 'This is where Dorius''s fall began. Unmasked as Lathoric the Black, he would boast that it was at this dig site that he came upon the Suntara stones and felt the power of Ragnaros flood into him. The find that seemed to doom his excavation team was, for him, a rebirth.', 'creature_text 8421 group 2 (stumbled upon the Suntara stones at the Grimesilt Digsite, the power of Ragnaros surged through my being); creature_text 8421 group 4 (reborn as an acolyte of fire, Lathoric the Black); smart_scripts 8417 (Lathoric 8391 summoned on accepting 3566), 8391 and script 839101 (Dorius 8421 spawned and speaks)'),
(5112, 1, 0, 255, 'His grief was a mask. When the towers of the Cauldron burned, the wronged man was gone and a drake of the black dragonflight stood in his place, a servant of the legion of Blackrock. The murdered father was only bait: no mortal, the drake mocked, would have lent a hand had Blackrock simply asked.', 'smart_scripts 8509 (Squire Maltrake: on quest 3463 rewarded, set data) and 8479 (Kalaran despawns, Kalaran the Deceiver 8480 summoned); creature_text 8480 groups 0, 2, 4 (my plan worked; you would not have helped the legion of Blackrock had we just asked); creature_template 8480 type 2 (dragonkin); warcraft.wiki.gg/wiki/Kalaran_Windblade (black drake)'),
(5113, 1, 4, 255, 'When researchers in Silithus began taking samples from the great colossi of the desert, Oilfist paid handsomely for the chitin of the Colossus of Regal, sure that the Brotherhood could devise incredibly powerful armor from it.', 'quest 8858 description (Thorium Point, Oilfist paying big) and reward text (incredibly powerful armor from this chitin); creature_questender 14625 quest 8858; mod-individual-progression aq_gate_quest.sql (8858 requires the Colossus of Regal quest, after the gong) and aq_war.sql, IndividualProgressionAwareness.cpp npc_ipp_aqwar (Colossus Researcher Eazel 15799, giver of 8858, visible only in state 4)'),
(5114, 1, 0, 255, 'With the plans recovered, Burninate hoped the traitor''s teeth had been kicked in too, and got down to business: rebuilding the Brotherhood''s dwindling supply of fiery flux from incendosaur scales, coal and whatever else its friends will bring. Those who prove themselves trusted friends of the Brotherhood he sends on to Lokhtos Darkbargainer at the Grim Guzzler in Blackrock Depths.', 'quest 7722 reward text (kicked his teeth in, now we can get down to business); quests 7736, 8241, 8242 completion texts (dwindling fiery flux supply; incendosaur scales, coal); npc_text 7121 (Lokhtos referral; conditions show it at honored or revered with the Thorium Brotherhood)'),
(5115, 1, 0, 255, 'When the traitor''s severed head was finally set before him, Lolo greeted it with slurred delight. He never thought he would see that ugly mug again, he declared, and the old face looked better without the rest of him attached.', 'quest 7701 reward text'),
(5118, 1, 0, 255, 'He never reached safety. Short of the gate a Dark Iron marksman brought him down, and the dwarf was gone in a cloud of dust, leaving only a singed letter for his brother. Written as a dead man''s last words, it told that the Dark Irons held the Suntara stones and that their leader, Lathoric the Black, was using them to enslave the excavation team.', 'smart_scripts 8284 and action list 828405 (Dark Iron Marksman summoned, Man Down, letter object 175704 summoned, quest explored); creature_text 8284 groups 5, 7 (He got me; disappears in a cloud of dust); quest 3367 reward text (letter dropped by Dorius when he was shot); quest 3368 description (the letter)'),
(5118, 2, 0, 255, 'Dorius never died. At the Grimesilt Dig Site he had stumbled upon the Suntara stones, and the power of Ragnaros surged through him. The Firelord gave him a purpose and a new name, Lathoric the Black, acolyte of fire. His wound and his death were a ruse to play on his brother''s grief and draw in rescuers. He means his creation Obsidion to destroy the Blackrock orcs of the Spire and unite the Dark Irons with their brethren in the fiery depths below.', 'creature_text 8421 groups 0-4, 6 (Lathoric''s confession); smart_scripts 8417 (Lathoric 8391 spawned on accepting 3566), 8391 and 839101; warcraft.wiki.gg/wiki/Lathoric_the_Black (Lathoric is Dorius)'),
(5120, 1, 0, 255, 'Curator Thorius of Ironforge knew Margol''s horn for what it was and hailed the beast as the bane of every archaeologist who ever dug in the Searing Gorge. Of Pebblebitty''s old meeting with Margol he would say only that there had been ''the incident'', and that the mountaineer had long wanted to kill the beast herself.', 'quest 3182 reward text (bane of every archaeologist); quest 3201 description (jealous, the ''incident''), offered by Thorius 8256 on the turn-in of 3182'),
(5121, 1, 0, 255, 'Pyron does not fall quietly. As he dies he swears that he will be reborn, for Lord Incendius shall raise him from the ashes, a sign that the fire lord of the quarry is only the servant of a greater power deeper within the mountain.', 'creature_text 9026 (I will be reborn, Incendius shall raise me), smart_scripts 9026 (said on death); quest 3906 reward text (Pyron''s destruction merely lifted a veil, a more insidious source within Blackrock); quest 4263 description (Incendius continues to raise Pyron)'),
(5122, 1, 0, 255, 'When the four towers burn, Squire Maltrake calls the sight glorious, and his master agrees, for it all went exactly as he planned. Kalaran casts off his disguise. He is a black drake, and the fires were set to open the gorge to the legion of Blackrock. Mockingly he lets his helpers live to see the chaos to come, leaves them a chest of trinkets and a molt of his flight that his kin in the Burning Steppes will know how to use, and takes wing.', 'quest 3463 reward text (It is glorious!); creature_text 8480, 8509 (the reveal); smart_scripts 8509, 8479 (Kalaran the Deceiver 8480 summoned on turning in 3463); gameobject 149502 Hoard of the Black Dragonflight (quest 3481)'),
(5123, 1, 0, 255, 'Within sight of the gate a Dark Iron marksman shoots him down, and Dorius vanishes in a cloud of dust, leaving a singed letter for his brother, Curator Thorius. It says the Suntara stones are real and in Dark Iron hands, that their leader Lathoric the Black uses them to enslave the excavation team, and that the captives toil in the Cauldron on something called Obsidion. Help them, it begs: it is the final wish of a dead man.', 'smart_scripts 828404, 828405 (Dark Iron Marksman summoned, Dorius falls, letter 175704 summoned); creature_text 8284 groups 5-7; quest 3367 reward text; quest 3368 description (the letter)'),
(5123, 2, 0, 255, 'Thorius sobbed over the letter, then wiped his face dry and vowed in the name of the Light that his brother would have his wish. With an empty hole where his heart had been, he sent rescuers back to the gorge to free Dorius''s men from the sweltering mine the Dark Irons call the Slag Pit, and to see the murderers brought to justice.', 'quest 3368 completion and reward texts (Thorius sobs, wipes his face, vows in the name of the Light); quest 3371 description (empty hole where my heart used to be; free his men; Slag Pit; perpetrators brought to justice), offered by Thorius 8256 on the turn-in of 3368 (RewardNextQuest)'),
(5123, 3, 0, 255, 'Deep in the pit, one of the enslaved archaeologists lies dying. Forget me, he pleads, help the others. The power of the Suntara will not let them rest even once their bodies fail, and only the altar of Suntara can release them: a relic held by the Twilight''s Hammer in the hills to the northwest must be laid upon it.', 'quest 3371 reward text (forget about me, help the others); quest 3372 description, offered by the Dying Archaeologist 8417 on the turn-in of 3371'),
(5123, 4, 0, 255, 'It was a trap. The relic was the last Suntara stone Lathoric needed, and the dying archaeologist can only beg forgiveness as Dorius himself appears, alive and mocking. Playing on his brother''s grief, he says, was all it took to bring rescuers to fetch it. Then Lathoric the Black, as Dorius is now named, calls Obsidion to rise and serve its master.', 'quest 3566 description (it was all a trap); creature_text 8421 (Bravo! You thought I was dead?; played upon my brother; last Suntara stone); creature_text 8391 (Obsidion, rise and serve your master); smart_scripts 8417 (Lathoric spawned on accepting 3566)'),
(5123, 5, 0, 255, 'When the head of Lathoric and the heart of Obsidion are laid before Thorius, the curator turns white. His own brother had set it all up, betraying him and all of Ironforge. Grief gives way to fury, and then to fear: if so noble a dwarf could be turned so easily to the will of Ragnaros, the influence of the Old Gods is still strong in these lands, and no one is safe.', 'quest 3566 log description and reward text'),
(5124, 1, 0, 255, 'Without the axe head, Pebblebitty calls the horn an obvious fake. She has been face to face with Margol, she insists, and the real horn is eight times larger; this one surely came off some stormsnout in the Barrens. If Curator Thorius in Ironforge will vouch for it, she says, a proof of deed will earn the key.', 'quest 3181 reward text; quest 3182 description'),
(5124, 2, 0, 255, 'In Ironforge, Curator Thorius could hardly believe his eyes: this was the horn of Margol the Rager, scourge of every archaeologist who ever worked the gorge, and might he keep it for the museum? After such a contribution a proof of deed was no trouble. As he filled out the large document, he confided that Pebblebitty was only jealous.', 'quest 3182 reward text; quest 3201 description (offered by Thorius on the turn-in of 3182)'),
(5124, 3, 0, 255, 'Pebblebitty could not argue with the curator''s signature. A deal is a deal, she grumbled, though she could not see how someone so weak had overcome Margol, and she handed over the key to the Searing Gorge with a warning: whatever happens beyond the gate is the bearer''s own fault.', 'quest 3201 reward text'),
(5125, 1, 0, 255, 'With the stolen plans back at Thorium Point, the recipe for fiery flux belongs to the Brotherhood again, and the quarrel can give way to the forge. Stocks of flux are running low, so Burninate now takes incendosaur scales, coal and other goods from the Brotherhood''s friends to make more.', 'quest 7722 reward text; quests 7736, 8241, 8242 completion texts'),
(5125, 2, 0, 255, 'Evonice''s scheme worked, or so she says. With their pillows gone, the sleepy Dark Irons of the Slag Pit began heading back to their homes in the Depths for rest, and the work of the pit slowed. Crazy goggles or not, she reminds anyone who doubts her, she is the smart one.', 'quest 7702 reward text and completion text (the crazy goggles, I''m the smart one)'),
(5126, 1, 0, 255, 'The poachers were only the beginning. Nilith names a greater enemy: the Undermarket, cutthroat traders who will sell, move or do just about anything for the right price. They have set up a base in the Cauldron under Trade Master Kovic, who keeps close ties with the Dark Iron dwarves, and Nilith wants Kovic and his minion Clunk slain to send a message to their leadership.', 'quest 3385 description (offered by Nilith on the turn-in of 3379)'),
(5126, 2, 0, 255, 'Kovic and Clunk fell in the Cauldron, a decisive blow that Nilith expects will make the Undermarket''s leaders think twice before sending more cronies into the gorge. The trader''s satchel held nothing of use to her, but the news itself she sends on to Vizzklick in Gadgetzan, sure he will be glad to hear it.', 'quest 3385 reward text; quest 3402 description (offered on the turn-in of 3385)'),
(5126, 3, 0, 255, 'Vizzklick could hardly believe it, and called it a glorious day. For years, he says, Kovic ran shady trades for the Undermarket, undercutting honest, hard working traders all over the world, and whoever ended him has earned a fine reward.', 'quest 3402 reward text');
